func testTopology() Topology {
	return Topology{Cell: "gru", Slots: []string{"controller-a", "controller-b", "controller-c"},
		SeedSlot: "controller-a", SelfSlot: "controller-a"}
}

func healthyObservation(at time.Time) Observation {
	return Observation{At: at,
		Meta: Meta{Leader: "gru-1-ctl-1", Size: 3, Peers: []Peer{
			{Name: "gru-1-ctl-2", Online: true, Current: true},
			{Name: "gru-1-ctl-3", Online: true, Current: true}}},
		Ledger: map[string]LedgerSlot{
			"controller-a": {Attempt: 1, InstanceOCID: instanceA, Complete: true},
			"controller-b": {Attempt: 1, InstanceOCID: instanceB, Complete: true},
			"controller-c": {Attempt: 1, InstanceOCID: instanceC, Complete: true}},
		Lifecycle: map[string]string{"controller-b": LifecycleRunning, "controller-c": LifecycleRunning},
		Evidence:  map[string]Evidence{},
	}
}

func withPeer(observation Observation, name string, online bool) Observation {
	peers := make([]Peer, 0, len(observation.Meta.Peers))
	for _, peer := range observation.Meta.Peers {
		if peer.Name == name {
			peer.Online = online
		}
		peers = append(peers, peer)
	}
	observation.Meta.Peers = peers
	return observation
}

func evidenceFor(slot string, attempt uint64, instance string) Evidence {
	return Evidence{Slot: slot, PreviousAttempt: attempt, PriorInstanceOCID: instance, Digest: evidenceID,
		Wire: []byte("signed")}
}

func lostB(at time.Time) Observation {
	observation := withPeer(healthyObservation(at), "gru-1-ctl-2", false)
	observation.Lifecycle["controller-b"] = LifecycleTerminated
	return observation
}

func withEvidenceB(o *Observation) {
	o.Evidence["controller-b"] = evidenceFor("controller-b", 1, instanceB)
}

func Decide(topology Topology, previous State, observation Observation) (State, []Action) {
	next := previous.clone()
	slots := slices.Clone(topology.Slots)
	slices.Sort(slots)
	online := make(map[string]bool, len(slots))
	for _, peer := range observation.Meta.Peers {
		online[peer.Name] = peer.Online
	}
	onlineSlots := 0
	for _, slot := range slots {
		if slot == topology.SelfSlot || online[topology.ServerName(slot)] {
			onlineSlots++
		}
	}
	quorum := observation.Meta.Leader != "" && onlineSlots >= topology.quorum()
	replacing := false
	for _, slot := range slots {
		status, ok := next.Slots[slot]
		if (!ok || status.Phase != PhaseReplacing) && slot != topology.SelfSlot && slot != topology.SeedSlot {
			if pending, inFlight := inFlightSuccessor(slot, observation); inFlight {
				// A new term, or a restarted leader, has no memory of a
				// replacement an earlier term admitted. The ledger does: its
				// incomplete successor HEAD is bound to this exact evidence, so
				// resume it instead of holding the slot as ledger-incomplete
				// and letting another slot start a concurrent replacement.
				status.Slot, status.Phase, status.PendingAttempt = slot, PhaseReplacing, pending
				next.Slots[slot] = status
				ok = true
			}
		}
		if ok && status.Phase == PhaseReplacing && abandonedBeforeAdmission(slot, status, observation) {
			// The successor was never admitted (the ledger still holds the
			// completed prior attempt) and the evidence that would let it be
			// admitted is gone. Nothing was launched, so release the gate and
			// hold the slot for fresh evidence instead of blocking every
			// other replacement for the rest of the term.
			status.Phase, status.PendingAttempt, status.LastFailure, status.LastError = PhaseHeld, 0, timeZero, ""
			next.Slots[slot] = status
		}
		if ok && status.Phase == PhaseReplacing || admittedSuccessor(observation.Ledger[slot]) {
			// The verified ledger HEAD reserves the single replacement slot
			// even when the evidence needed to resume it is not on hand:
			// the founder persists the successor HEAD before any OCI launch.
			replacing = true
		}
	}
	var actions []Action
	for _, slot := range slots {
		status := next.Slots[slot]
		status.Slot = slot
		ledger := observation.Ledger[slot]
		lifecycle := observation.Lifecycle[slot]
		status.Attempt, status.InstanceOCID, status.Lifecycle = ledger.Attempt, ledger.InstanceOCID, lifecycle
		status.Online = slot == topology.SelfSlot || online[topology.ServerName(slot)]
		evidence, hasEvidence := observation.Evidence[slot]
		if status.Phase == PhaseReplacing {
			status, actions = decideReplacing(status, ledger, evidence, hasEvidence, quorum, observation, actions)
			next.Slots[slot] = status
			continue
		}
		switch {
		case slot == topology.SelfSlot:
			status = healthy(status, ReasonLocal)
			next.Slots[slot] = status
			continue
		case status.Online && lifecycle == LifecycleTerminated && ledger.Complete:
			status.Phase, status.Reason = PhaseHeld, ReasonTerminatedButOnline
			next.Slots[slot] = status
			continue
		case status.Online:
			next.Slots[slot] = healthy(status, ReasonOnline)
			continue
		}
		if status.OfflineSince.IsZero() {
			status.OfflineSince = observation.At
		}
		terminated := lifecycle == LifecycleTerminated
		if !terminated && observation.At.Sub(status.OfflineSince) < DefaultOfflineGrace {
			status.Phase, status.Reason = PhaseSuspect, ReasonOfflineWithinGrace
			next.Slots[slot] = status
			continue
		}
		status.Phase = PhaseHeld
		switch {
		case slot == topology.SeedSlot:
			status.Reason = ReasonSeedSlot
		case ledger.Complete && ledger.Attempt == 0 && ledger.InstanceOCID != "":
			status.Reason = "accepted controller has no current replacement launch authority"
		case !ledger.Complete || ledger.Attempt == 0 || ledger.InstanceOCID == "":
			status.Reason = ReasonLedgerIncomplete
		case lifecycle == "":
			status.Reason = ReasonInstanceUnobserved
		case !terminated:
			status.Reason = fmt.Sprintf("%s (%s is %s)", ReasonInstanceAlive, ledger.InstanceOCID, lifecycle)
		case !quorum:
			status.Reason = ReasonQuorumLost
		case replacing:
			status.Reason = ReasonOtherReplacement
		case !hasEvidence || evidence.Slot != slot || evidence.PreviousAttempt != ledger.Attempt ||
			evidence.PriorInstanceOCID != ledger.InstanceOCID || len(evidence.Wire) == 0:
			status.Reason = fmt.Sprintf("%s for %s attempt %d instance %s", ReasonAwaitingEvidence, slot,
				ledger.Attempt, ledger.InstanceOCID)
		case !status.LastFailure.IsZero() && observation.At.Sub(status.LastFailure) < DefaultRetryBackoff:
			status.Reason = ReasonRetryBackoff
		default:
			status.Phase, status.Reason = PhaseReplacing, ReasonReplacing
			status.PendingAttempt = ledger.Attempt + 1
			replacing = true
			actions = append(actions, Action{Slot: slot, PreviousAttempt: ledger.Attempt,
				PriorInstanceOCID: ledger.InstanceOCID, Retirement: evidence,
				Reason: "pinned instance " + ledger.InstanceOCID + " is terminated"})
		}
		next.Slots[slot] = status
	}
	return next, actions
}

func decideReplacing(status SlotStatus, ledger LedgerSlot, evidence Evidence, hasEvidence bool,
	quorum bool, observation Observation, actions []Action,
) (SlotStatus, []Action) {
	previous := status.PendingAttempt - 1
	if ledger.Attempt >= status.PendingAttempt && ledger.Complete {
		status.PendingAttempt, status.LastFailure, status.LastError = 0, timeZero, ""
		if status.Online {
			return healthy(status, ReasonOnline), actions
		}
		// The successor gets a fresh grace to start and catch up.
		status.Phase, status.Reason, status.OfflineSince = PhaseSuspect, ReasonRejoining, observation.At
		return status, actions
	}
	switch {
	case !quorum:
		status.Reason = ReasonQuorumLost
	case !hasEvidence || evidence.Slot != status.Slot || evidence.PreviousAttempt != previous ||
		ledger.Attempt != previous && ledger.Attempt != status.PendingAttempt || len(evidence.Wire) == 0:
		status.Reason = fmt.Sprintf("%s for %s attempt %d", ReasonAwaitingEvidence, status.Slot, previous)
	case !status.LastFailure.IsZero() && observation.At.Sub(status.LastFailure) < DefaultRetryBackoff:
		status.Reason = ReasonRetryBackoff
	default:
		status.Reason = ReasonReplacing
		actions = append(actions, Action{Slot: status.Slot, PreviousAttempt: previous,
			PriorInstanceOCID: evidence.PriorInstanceOCID, Retirement: evidence, Reason: "resume replacement"})
	}
	return status, actions
}

func inFlightSuccessor(slot string, observation Observation) (uint64, bool) {
	ledger := observation.Ledger[slot]
	evidence, ok := observation.Evidence[slot]
	if !ok || ledger.Complete || ledger.Attempt < 2 || ledger.Retirement == "" ||
		evidence.Slot != slot || evidence.Digest != ledger.Retirement ||
		evidence.PreviousAttempt+1 != ledger.Attempt || len(evidence.Wire) == 0 {
		return 0, false
	}
	return ledger.Attempt, true
}

func admittedSuccessor(ledger LedgerSlot) bool {
	return !ledger.Complete && ledger.Attempt >= 2 && ledger.Retirement != ""
}

func abandonedBeforeAdmission(slot string, status SlotStatus, observation Observation) bool {
	previous := status.PendingAttempt - 1
	ledger := observation.Ledger[slot]
	if status.PendingAttempt == 0 || !ledger.Complete || ledger.Attempt != previous {
		return false
	}
	evidence, ok := observation.Evidence[slot]
	return !ok || evidence.Slot != slot || evidence.PreviousAttempt != previous || len(evidence.Wire) == 0
}

func healthy(status SlotStatus, reason string) SlotStatus {
	status.Phase, status.Reason = PhaseHealthy, reason
	status.OfflineSince, status.PendingAttempt, status.LastFailure, status.LastError = timeZero, 0, timeZero, ""
	return status
}

func (t Topology) Validate() error {
	if t.Cell == "" || len(t.Slots) < 1 || len(t.Slots)%2 == 0 || len(t.Slots) > 5 ||
		!slices.Contains(t.Slots, t.SeedSlot) || !slices.Contains(t.Slots, t.SelfSlot) {
		return errors.New("membership topology needs an odd slot set containing the seed and local slot")
	}
	seen := make(map[string]struct{}, len(t.Slots))
	for _, slot := range t.Slots {
		if slot == "" {
			return errors.New("membership topology has an empty slot")
		}
		if _, exists := seen[slot]; exists {
			return errors.New("membership topology repeats a slot")
		}
		seen[slot] = struct{}{}
	}
	return nil
}

func (s State) clone() State {
	slots := make(map[string]SlotStatus, len(s.Slots))
	for slot, status := range s.Slots {
		slots[slot] = status
	}
	return State{Slots: slots}
}

func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

func (c Cell) Server(role string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-%s-%d", strings.ToLower(c.Region), c.Index, role, n))
}

func (c Cell) ControllerSlot(slot string) (string, error) {
	if strings.ToUpper(c.Region) == catalog.GRU {
		return c.slot(slot, "controller-", Controller)
	}
	letter, ok := strings.CutPrefix(slot, "controller-")
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: controller-slot %q", ErrName, slot)
	}
	return c.Node(int(letter[0]-'a') + 1)
}

func (c Cell) slot(slot, prefix, role string) (string, error) {
	letter, ok := strings.CutPrefix(slot, prefix)
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: %sslot %q", ErrName, prefix, slot)
	}
	return c.Server(role, int(letter[0]-'a')+1)
}

func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil
}

func NATSServer(cell, instance string) string {
	if name, err := RegionCell(cell).ControllerSlot(instance); err == nil {
		return name
	}
	return cell + "-" + instance
}

func valid(name string) (string, error) {
	if err := Validate(name); err != nil {
		return "", err
	}
	return name, nil
}

const (
	DefaultInterval     = 10 * time.Second
	DefaultOfflineGrace = 10 * time.Minute
	DefaultRetryBackoff = 5 * time.Minute
	// DefaultRetirementEvidenceDir holds operator-supplied, root-signed slot
	// retirement envelopes named <slot>.retirement, and the leader's unsigned
	// <slot>.retirement-request.json files. It lives under the controller
	// unit's StateDirectory, the only tree the service account may write
	// under ProtectSystem=strict. systemd creates the StateDirectory itself;
	// the controller creates this subdirectory (0700) when it first writes a
	// retirement request.
	DefaultRetirementEvidenceDir = "/var/lib/terrascale-orchestrator-controller/membership/retirement"
)

func leaderSnapshot(epoch uint64) authority.Snapshot {
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true, Leader: true, Epoch: epoch, Revision: 1,
		ExpiresAt: time.Now().Add(time.Hour)}
}

func (f *fakeLeadership) Current() authority.Snapshot {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.snapshot
}

func (f *fakeLeadership) Guard(_ context.Context, epoch uint64) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.guards++
	if f.guardErr != nil {
		return f.guardErr
	}
	if f.snapshot.Epoch != epoch {
		return authority.ErrFenced
	}
	return nil
}

func (f *fakeCell) Meta(context.Context) (Meta, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.meta, f.metaErr
}

func (f *fakeCell) Slots(_ context.Context, slots []string) (map[string]LedgerSlot, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make(map[string]LedgerSlot, len(slots))
	for _, slot := range slots {
		out[slot] = f.ledger[slot]
	}
	return out, nil
}

func (f *fakeCell) Lifecycle(_ context.Context, instance string) (string, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	state, ok := f.lifecycle[instance]
	if !ok {
		return "", errors.New("instance not found")
	}
	return state, nil
}

func (f *fakeCell) Evidence(context.Context) (map[string]Evidence, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.evidence, nil
}

func (f *fakeCell) Replace(_ context.Context, action Action) error {
	f.mu.Lock()
	f.replaced = append(f.replaced, action)
	replace := f.replace
	f.mu.Unlock()
	if replace != nil {
		return replace(action)
	}
	return nil
}

func newFakeCell() *fakeCell {
	observation := lostB(testEpoch)
	return &fakeCell{meta: observation.Meta, ledger: observation.Ledger,
		lifecycle: map[string]string{instanceB: LifecycleTerminated, instanceC: LifecycleRunning},
		evidence:  map[string]Evidence{"controller-b": evidenceFor("controller-b", 1, instanceB)}}
}

func newTestReconciler(t *testing.T, leader *fakeLeadership, cell *fakeCell, replacer Replacer,
	clock *time.Time,
) *Reconciler {
	t.Helper()
	reconciler, err := New(testTopology(), Dependencies{Leadership: leader, Peers: cell, Ledger: cell,
		Instances: cell, Evidence: cell, Replacer: replacer, Now: func() time.Time { return *clock },
		Logger: slog.New(slog.NewTextHandler(io.Discard, nil))})
	if err != nil {
		t.Fatal(err)
	}
	return reconciler
}

func statusOf(r *Reconciler, slot string) SlotStatus {
	for _, status := range r.Statuses() {
		if status.Slot == slot {
			return status
		}
	}
	return SlotStatus{}
}

func (r *recordingRequests) RequestRetirement(_ context.Context, request RetirementRequest) error {
	r.requests = append(r.requests, request)
	return nil
}

func New(topology Topology, deps Dependencies) (*Reconciler, error) {
	if err := topology.Validate(); err != nil {
		return nil, err
	}
	if deps.Leadership == nil || deps.Peers == nil || deps.Ledger == nil || deps.Instances == nil ||
		deps.Evidence == nil {
		return nil, errors.New("membership reconciler dependencies are incomplete")
	}
	if deps.Now == nil {
		deps.Now = time.Now
	}
	if deps.Logger == nil {
		deps.Logger = slog.Default()
	}
	return &Reconciler{topology: topology, deps: deps,
		state: State{Slots: make(map[string]SlotStatus)}, requested: make(map[string]retirementRequestMark)}, nil
}

func (r *Reconciler) Statuses() []SlotStatus {
	r.mu.Lock()
	defer r.mu.Unlock()
	return slices.Clone(r.statuses)
}

// Tick is one complete observe, decide and act pass.
func (r *Reconciler) Tick(ctx context.Context) error {
	snapshot := r.deps.Leadership.Current()
	if !snapshot.CanMutate() {
		r.reset(0)
		return nil
	}
	r.mu.Lock()
	if r.epoch != snapshot.Epoch {
		// A new term starts every grace period from its own observations.
		r.state, r.epoch = State{Slots: make(map[string]SlotStatus)}, snapshot.Epoch
		r.requested = make(map[string]retirementRequestMark)
	}
	previous := r.state.clone()
	r.mu.Unlock()
	observation, err := r.observe(ctx)
	if err != nil {
		return err
	}
	next, actions := Decide(r.topology, previous, observation)
	for _, action := range actions {
		next.Slots[action.Slot] = r.execute(ctx, snapshot.Epoch, action, next.Slots[action.Slot], observation.At)
	}
	r.requestRetirements(ctx, snapshot.Epoch, next, observation)
	r.commit(snapshot.Epoch, previous, next)
	return nil
}

func (r *Reconciler) requestRetirements(ctx context.Context, epoch uint64, next State, observation Observation) {
	if r.deps.Requests == nil {
		return
	}
	for _, slot := range r.topology.Slots {
		status := next.Slots[slot]
		if status.Phase != PhaseHeld || status.Lifecycle != LifecycleTerminated ||
			!strings.HasPrefix(status.Reason, ReasonAwaitingEvidence) {
			continue
		}
		r.mu.Lock()
		mark := r.requested[slot]
		done := mark.attempt == status.Attempt && observation.At.Sub(mark.at) < RetirementRequestRefresh
		r.mu.Unlock()
		if done {
			continue
		}
		err := r.deps.Requests.RequestRetirement(ctx, RetirementRequest{Slot: slot, Attempt: status.Attempt,
			InstanceOCID: status.InstanceOCID, Lifecycle: status.Lifecycle, MetaLeader: observation.Meta.Leader,
			OfflineSince: status.OfflineSince, ObservedAt: observation.At, Epoch: epoch})
		if err != nil {
			r.deps.Logger.Warn("controller slot retirement request failed", "slot", slot, "error", err)
			continue
		}
		r.deps.Logger.Info("controller slot retirement evidence requested", "slot", slot,
			"attempt", status.Attempt, "instance", status.InstanceOCID)
		r.mu.Lock()
		r.requested[slot] = retirementRequestMark{attempt: status.Attempt, at: observation.At}
		r.mu.Unlock()
	}
}

func (r *Reconciler) observe(ctx context.Context) (Observation, error) {
	meta, err := r.deps.Peers.Meta(ctx)
	if err != nil {
		return Observation{}, fmt.Errorf("read JetStream metadata peers: %w", err)
	}
	ledger, err := r.deps.Ledger.Slots(ctx, r.topology.Slots)
	if err != nil {
		return Observation{}, fmt.Errorf("read controller slot ledger: %w", err)
	}
	lifecycle := make(map[string]string, len(ledger))
	for _, slot := range r.topology.Slots {
		pinned := ledger[slot]
		if slot == r.topology.SelfSlot || pinned.InstanceOCID == "" {
			continue
		}
		state, err := r.deps.Instances.Lifecycle(ctx, pinned.InstanceOCID)
		if err != nil {
			if ctx.Err() != nil {
				return Observation{}, ctx.Err()
			}
			// An unobservable instance is held, never assumed terminated.
			r.deps.Logger.Debug("controller slot instance unobservable", "slot", slot, "error", err)
			continue
		}
		lifecycle[slot] = state
	}
	evidence, err := r.deps.Evidence.Evidence(ctx)
	if err != nil {
		return Observation{}, fmt.Errorf("read retirement evidence: %w", err)
	}
	return Observation{At: r.deps.Now().UTC(), Meta: meta, Ledger: ledger, Lifecycle: lifecycle,
		Evidence: evidence}, nil
}

func (r *Reconciler) execute(ctx context.Context, epoch uint64, action Action, status SlotStatus,
	at time.Time,
) SlotStatus {
	fail := func(err error) SlotStatus {
		status.LastFailure, status.LastError = at, err.Error()
		r.deps.Logger.Warn("controller slot replacement failed", "slot", action.Slot,
			"previous_attempt", action.PreviousAttempt, "error", err)
		return status
	}
	unavailable := func() SlotStatus {
		// Report the decision, but do not hold the single replacement slot.
		status = fail(ErrReplacerUnavailable)
		status.Phase, status.Reason, status.PendingAttempt = PhaseHeld, ErrReplacerUnavailable.Error(), 0
		return status
	}
	if r.deps.Replacer == nil {
		return unavailable()
	}
	if err := r.deps.Leadership.Guard(ctx, epoch); err != nil {
		return fail(fmt.Errorf("authority fence: %w", err))
	}
	r.deps.Logger.Info("replacing controller slot", "slot", action.Slot, "previous_attempt", action.PreviousAttempt,
		"prior_instance", action.PriorInstanceOCID, "reason", action.Reason, "epoch", epoch)
	// The term's fence extends through the whole replacement: the context
	// ends as soon as this controller stops holding the epoch, and the
	// replacer rechecks the guard right before each mutation.
	fencedCtx, stopFence := r.termContext(ctx, epoch)
	defer stopFence()
	action.Epoch = epoch
	action.Fence = func(fenceCtx context.Context) error { return r.deps.Leadership.Guard(fenceCtx, epoch) }
	if err := r.deps.Replacer.Replace(fencedCtx, action); err != nil {
		if errors.Is(err, ErrReplacerUnavailable) {
			return unavailable()
		}
		return fail(err)
	}
	status.LastFailure, status.LastError = timeZero, ""
	r.recordReplacement(ctx, epoch, action)
	return status
}

func (r *Reconciler) termContext(ctx context.Context, epoch uint64) (context.Context, context.CancelFunc) {
	termCtx, cancel := context.WithCancelCause(ctx)
	go func() {
		ticker := time.NewTicker(termFencePoll)
		defer ticker.Stop()
		for {
			select {
			case <-termCtx.Done():
				return
			case <-ticker.C:
				if snapshot := r.deps.Leadership.Current(); !snapshot.CanMutate() || snapshot.Epoch != epoch {
					cancel(errors.New("controller authority term ended during slot replacement"))
					return
				}
			}
		}
	}()
	return termCtx, func() { cancel(context.Canceled) }
}

func (r *Reconciler) recordReplacement(ctx context.Context, epoch uint64, action Action) {
	key := fmt.Sprintf("membership:%s:%d", action.Slot, action.PreviousAttempt)
	if decisionlog.Correlated(key) != "" {
		return
	}
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Region:  r.topology.Cell,
		Actor:   decisionlog.Actor{Slice: "membership"},
		Kind:    decisionlog.KindControllerReplaced,
		Subject: decisionlog.Subject{Kind: "member", ID: r.topology.ServerName(action.Slot), Name: action.Slot},
		Summary: fmt.Sprintf("Replacing controller slot %s as attempt %d", action.Slot, action.PreviousAttempt+1),
		Reason:  "The slot was lost and root-signed retirement evidence names its exact prior instance.",
		Rule:    "membership." + action.Reason,
		Signals: []decisionlog.Signal{{Name: "prior_attempt", Value: float64(action.PreviousAttempt)}},
		Status:  decisionlog.StatusInProgress,
		Epoch:   epoch,
		Attrs:   map[string]string{"prior_instance": action.PriorInstanceOCID, "retirement": action.Retirement.Digest},
	})
	decisionlog.Correlate(key, id)
}

func (r *Reconciler) commit(epoch uint64, previous, next State) {
	statuses := make([]SlotStatus, 0, len(next.Slots))
	for _, slot := range r.topology.Slots {
		status := next.Slots[slot]
		statuses = append(statuses, status)
		before, existed := previous.Slots[slot]
		if !existed || before.Phase != status.Phase || before.Reason != status.Reason {
			r.deps.Logger.Info("controller slot membership", "slot", slot, "phase", status.Phase,
				"reason", status.Reason, "attempt", status.Attempt, "online", status.Online,
				"lifecycle", status.Lifecycle)
		}
	}
	slices.SortFunc(statuses, func(a, b SlotStatus) int {
		switch {
		case a.Slot < b.Slot:
			return -1
		case a.Slot > b.Slot:
			return 1
		}
		return 0
	})
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.epoch == epoch {
		r.state, r.statuses = next, statuses
	}
}

func (r *Reconciler) reset(epoch uint64) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.state, r.epoch, r.statuses = State{Slots: make(map[string]SlotStatus)}, epoch, nil
	r.requested = make(map[string]retirementRequestMark)
}

func (s Snapshot) CanMutate() bool {
	return entityid.Valid(s.DeploymentID) && s.Ready && s.Leader && s.Epoch > 0 && s.Revision > 0 &&
		!s.ExpiresAt.IsZero() && time.Now().Before(s.ExpiresAt)
}

func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

// Record journals one decision with the process-wide recorder and returns
// its ID, so a caller can link later decisions to it with ParentID. It never
// blocks on the network and never fails; see the package documentation.
func Record(ctx context.Context, decision Decision) string {
	if recorder := Default(); recorder != nil {
		return recorder.Record(ctx, decision)
	}
	return LogRecorder{}.Record(ctx, decision)
}

func (recorder LogRecorder) Record(ctx context.Context, decision Decision) string {
	decision = decision.Normalize(time.Now())
	logger := recorder.Logger
	if logger == nil {
		logger = slog.Default()
	}
	attrs := []slog.Attr{slog.String(observability.ComponentKey, "decision"), slog.Bool(observability.EventKey, true),
		slog.String("decision_id", decision.ID),
		slog.String("kind", string(decision.Kind)), slog.String("actor", decision.Actor.Slice),
		slog.String("subject", decision.Subject.String()), slog.String("status", string(decision.Status))}
	if decision.Region != "" {
		attrs = append(attrs, slog.String("region", decision.Region))
	}
	if decision.Reason != "" {
		attrs = append(attrs, slog.String("reason", decision.Reason))
	}
	if decision.ParentID != "" {
		attrs = append(attrs, slog.String("parent_id", decision.ParentID))
	}
	logger.LogAttrs(ctx, slog.LevelInfo, decision.Summary, attrs...)
	return decision.ID
}

func Correlate(key, id string) {
	if key == "" || id == "" {
		return
	}
	correlations.Lock()
	defer correlations.Unlock()
	if _, exists := correlations.ids[key]; !exists {
		correlations.order = append(correlations.order, key)
	}
	correlations.ids[key] = id
	for len(correlations.order) > maxCorrelations {
		delete(correlations.ids, correlations.order[0])
		correlations.order = correlations.order[1:]
	}
}

// Correlated returns the decision ID remembered for key, or "".
func Correlated(key string) string {
	correlations.Lock()
	defer correlations.Unlock()
	return correlations.ids[key]
}

func (replacer *blockingReplacer) Replace(ctx context.Context, action Action) error {
	replacer.fence = action.Fence
	close(replacer.started)
	<-ctx.Done()
	replacer.ended <- context.Cause(ctx)
	return ctx.Err()
}

func NewFileEvidence(dir string, slots []string, logger *slog.Logger) FileEvidence {
	return FileEvidence{Dir: dir, Slots: slots, Logger: logger, reported: new(sync.Map)}
}

func (source FileEvidence) Evidence(ctx context.Context) (map[string]Evidence, error) {
	evidence := make(map[string]Evidence, len(source.Slots))
	if source.Dir == "" {
		return evidence, nil
	}
	for _, slot := range source.Slots {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		wire, err := readEvidenceFile(filepath.Join(source.Dir, slot+EvidenceFileSuffix))
		if errors.Is(err, os.ErrNotExist) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("read %s retirement evidence: %w", slot, err)
		}
		decoded, err := bootstrap.DecodeSlotRetirementCandidate(wire)
		if err != nil || decoded.Slot != slot {
			// A malformed or misplaced file is ignored rather than trusted.
			sum := sha256.Sum256(wire)
			if _, seen := source.loadOrStoreReported(slot, sum); source.Logger != nil && !seen {
				reason := "envelope names another slot"
				if err != nil {
					reason = err.Error()
				}
				source.Logger.Warn("retirement evidence file ignored", "slot", slot,
					"file", slot+EvidenceFileSuffix, "reason", reason)
			}
			continue
		}
		sum := sha256.Sum256(wire)
		evidence[slot] = Evidence{Slot: slot, PreviousAttempt: decoded.PreviousAttempt,
			PriorInstanceOCID: decoded.PriorInstanceOCID, Digest: hex.EncodeToString(sum[:]), Wire: wire}
	}
	return evidence, nil
}

func readEvidenceFile(path string) ([]byte, error) {
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		if errors.Is(err, unix.ENOENT) {
			return nil, os.ErrNotExist
		}
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		return nil, err
	}
	if stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Mode&0o077 != 0 || stat.Uid != uint32(os.Geteuid()) &&
		stat.Uid != 0 || stat.Size <= 0 || stat.Size > maxEvidenceBytes {
		return nil, errors.New("retirement evidence must be a bounded owner-only regular file")
	}
	wire, err := io.ReadAll(io.LimitReader(file, maxEvidenceBytes+1))
	if err != nil {
		return nil, err
	}
	if len(wire) > maxEvidenceBytes || int64(len(wire)) != stat.Size {
		return nil, errors.New("retirement evidence changed while reading")
	}
	return wire, nil
}

func (source FileEvidence) loadOrStoreReported(slot string, sum [sha256.Size]byte) (any, bool) {
	if source.reported == nil {
		return nil, false
	}
	return source.reported.LoadOrStore(slot+"/"+hex.EncodeToString(sum[:]), struct{}{})
}

func ValidateSlotRetirementCandidate(evidence RetirementEvidence) error {
	if evidence.SchemaVersion != 1 || evidence.Role != roleController || evidence.Slot == "" ||
		!ledgerIDPattern.MatchString(evidence.Slot) || evidence.DeploymentID == "" || evidence.Cell == "" ||
		evidence.Environment == "" || evidence.PreviousAttempt == 0 || evidence.PreviousGeneration == 0 ||
		!validDigest(evidence.PreviousResultDigest) || !isOCID(evidence.PriorInstanceOCID, "instance") ||
		evidence.PriorCreateKey == "" || evidence.Disposition != SlotRetirementDisposition ||
		evidence.CoordinatorHandoffDigest != "" || !validDigest(evidence.ObservedEvidenceDigest) ||
		evidence.FencingAuthority == "" || !validFounderNow(evidence.ObservedAt) {
		return fmt.Errorf("%w: retirement candidate is incomplete", ErrRetirementInvalid)
	}
	return nil
}

func SignSlotRetirement(evidence RetirementEvidence, issuedAt, expiresAt time.Time,
	rootPrivateKey ed25519.PrivateKey,
) (trust.Envelope, error) {
	if err := ValidateSlotRetirementCandidate(evidence); err != nil {
		return trust.Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validFounderNow(issuedAt) || !expiresAt.After(issuedAt) || issuedAt.Before(evidence.ObservedAt) ||
		expiresAt.Sub(issuedAt) > MaxSlotRetirementLifetime {
		return trust.Envelope{}, fmt.Errorf("%w: retirement signing interval is invalid", ErrRetirementInvalid)
	}
	payload, err := trust.EncodePayload(evidence)
	if err != nil {
		return trust.Envelope{}, err
	}
	return trust.Sign(payload, trust.Scope{Domain: domainSlotRetirement, DeploymentID: evidence.DeploymentID,
		Cell: evidence.Cell, Environment: evidence.Environment, Role: roleController, Slot: evidence.Slot},
		issuedAt, expiresAt, rootPrivateKey)
}

func DecodeSlotRetirementCandidate(wire []byte) (RetirementEvidence, error) {
	if len(wire) == 0 || len(wire) > maxLedgerRecordBytes {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil || envelope.Scope.Domain != domainSlotRetirement {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	var evidence RetirementEvidence
	if err := decodeCanonicalPayload(envelope.Payload, &evidence); err != nil {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	if err := ValidateSlotRetirementCandidate(evidence); err != nil {
		return RetirementEvidence{}, err
	}
	if envelope.Scope != (trust.Scope{Domain: domainSlotRetirement, DeploymentID: evidence.DeploymentID,
		Cell: evidence.Cell, Environment: evidence.Environment, Role: roleController, Slot: evidence.Slot}) {
		return RetirementEvidence{}, ErrRetirementInvalid
	}
	return evidence, nil
}

func EncodeEnvelope(envelope Envelope) ([]byte, error) {
	if err := envelope.validateShape(); err != nil {
		return nil, err
	}
	encoded, err := json.Marshal(envelope, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust envelope: %w", err)
	}
	if len(encoded) > MaxEnvelopeBytes {
		return nil, fmt.Errorf("%w: encoded envelope exceeds size limit", ErrInvalid)
	}
	return encoded, nil
}

func DecodeEnvelope(encoded []byte) (Envelope, error) {
	if len(encoded) == 0 || len(encoded) > MaxEnvelopeBytes {
		return Envelope{}, fmt.Errorf("%w: envelope is empty or too large", ErrInvalid)
	}
	var envelope Envelope
	if err := protocol.DecodeStrict(encoded, &envelope, MaxEnvelopeBytes); err != nil {
		return Envelope{}, fmt.Errorf("decode trust envelope: %w", err)
	}
	canonical, err := EncodeEnvelope(envelope)
	if err != nil {
		return Envelope{}, err
	}
	if string(canonical) != string(encoded) {
		return Envelope{}, fmt.Errorf("%w: envelope JSON is not canonical", ErrInvalid)
	}
	return envelope, nil
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

func decodeCanonicalPayload(data []byte, destination any) error {
	if err := protocol.DecodeStrict(data, destination, maxLedgerRecordBytes); err != nil {
		return err
	}
	encoded, err := protocol.EncodeJSON(destination)
	if err != nil {
		return err
	}
	if !bytes.Equal(encoded, data) {
		return errors.New("bootstrap payload is not deterministic JSON")
	}
	return nil
}

func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

