func completeLedger() map[string]LedgerSlot {
	return map[string]LedgerSlot{
		"controller-a": {Attempt: 1, InstanceOCID: instanceA, Complete: true},
		"controller-b": {Attempt: 1, InstanceOCID: instanceB, Complete: true},
		"controller-c": {Attempt: 1, InstanceOCID: instanceC, Complete: true},
	}
}

func (pending RefoundPending) validate() error {
	serverName, err := naming.RegionCell(pending.Cell).ControllerSlot(pending.Slot)
	if err != nil || pending.ServerName != serverName || pending.Attempt < 2 || pending.StartedAt.IsZero() {
		return errors.New("pending refound record lacks an exact regional slot, successor attempt or start time")
	}
	return nil
}

func (guard RefoundGuard) now() time.Time {
	if guard.Now != nil {
		return guard.Now().UTC()
	}
	return time.Now().UTC()
}

func (guard RefoundGuard) Admit(cell, slot string, ledger map[string]LedgerSlot) error {
	others := make([]string, 0, len(ledger))
	for other := range ledger {
		others = append(others, other)
	}
	slices.Sort(others)
	for _, other := range others {
		head := ledger[other]
		if other != slot && !head.Complete && head.Attempt >= 2 {
			return fmt.Errorf("slot %s has an incomplete re-founded attempt %d; wait until it completes and reports current before re-founding %s",
				other, head.Attempt, slot)
		}
	}
	pending, err := guard.readPending()
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read the pending refound record %s: %w", guard.PendingPath, err)
	}
	if pending.Cell != cell {
		return fmt.Errorf("pending refound belongs to cell %s, not %s", pending.Cell, cell)
	}
	if pending.Slot == slot {
		// The same slot may be retried after interruption.
		return nil
	}
	if err := guard.current(pending); err != nil {
		return fmt.Errorf("slot %s re-founded at %s is not current yet (%v); re-found one slot at a time",
			pending.Slot, pending.StartedAt.Format(time.RFC3339), err)
	}
	return guard.Clear()
}

func (guard RefoundGuard) Begin(pending RefoundPending) error {
	if err := pending.validate(); err != nil {
		return err
	}
	wire, err := json.Marshal(pending)
	if err != nil {
		return err
	}
	return writeOwnerOnly(guard.PendingPath, wire)
}

func (guard RefoundGuard) Clear() error {
	if err := os.Remove(guard.PendingPath); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	return syncDir(filepath.Dir(guard.PendingPath))
}

func (guard RefoundGuard) current(pending RefoundPending) error {
	if err := pending.validate(); err != nil {
		return err
	}
	status, err := clusterhealth.ReadStatusFile(guard.HealthPath)
	if err != nil {
		return fmt.Errorf("read the controller's cluster health %s: %w", guard.HealthPath, err)
	}
	notBefore := guard.now().Add(-RefoundHealthFreshness)
	if pending.StartedAt.After(notBefore) {
		notBefore = pending.StartedAt
	}
	return status.PeerCurrent(pending.ServerName, notBefore)
}

func (guard RefoundGuard) Lock() (release func(), err error) {
	path := guard.PendingPath + ".lock"
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, err
	}
	file, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, fmt.Errorf("open the refound lock %s: %w", path, err)
	}
	if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		file.Close()
		if errors.Is(err, syscall.EWOULDBLOCK) {
			return nil, errors.New("another break-glass refound is running on this host; re-found one slot at a time")
		}
		return nil, fmt.Errorf("lock %s: %w", path, err)
	}
	return func() {
		_ = syscall.Flock(int(file.Fd()), syscall.LOCK_UN)
		file.Close()
	}, nil
}

func (guard RefoundGuard) readPending() (RefoundPending, error) {
	file, err := os.OpenFile(guard.PendingPath, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return RefoundPending{}, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return RefoundPending{}, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || info.Size() <= 0 || info.Size() > 4<<10 {
		return RefoundPending{}, errors.New("pending refound record must be a small owner-only regular file")
	}
	wire, err := io.ReadAll(io.LimitReader(file, (4<<10)+1))
	if err != nil {
		return RefoundPending{}, err
	}
	var pending RefoundPending
	if err := protocol.DecodeStrict(wire, &pending, 4<<10); err != nil {
		return RefoundPending{}, errors.New("pending refound record is malformed")
	}
	if err := pending.validate(); err != nil {
		return RefoundPending{}, err
	}
	return pending, nil
}

func writeOwnerOnly(path string, data []byte) error {
	dir := filepath.Dir(path)
	if _, err := os.Stat(dir); errors.Is(err, os.ErrNotExist) {
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return err
		}
		if err := syncDir(filepath.Dir(dir)); err != nil {
			return err
		}
	}
	temporary, err := os.CreateTemp(dir, ".refound-*")
	if err != nil {
		return err
	}
	defer os.Remove(temporary.Name())
	if err := temporary.Chmod(0o600); err != nil {
		temporary.Close()
		return err
	}
	if _, err := temporary.Write(data); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Sync(); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}
	if err := os.Rename(temporary.Name(), path); err != nil {
		return err
	}
	// The record gates the next slot after a crash, so its directory entry
	// must be durable before the caller launches anything.
	return syncDir(dir)
}

func syncDir(dir string) error {
	handle, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer handle.Close()
	return handle.Sync()
}

func WriteStatusFile(path string, status Status) error {
	if path == "" || !filepath.IsAbs(path) {
		return errors.New("cluster health status file path must be absolute")
	}
	wire, err := json.Marshal(status)
	if err != nil {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	temporary, err := os.CreateTemp(dir, ".cluster-health-*")
	if err != nil {
		return err
	}
	defer os.Remove(temporary.Name())
	if err := temporary.Chmod(0o600); err != nil {
		temporary.Close()
		return err
	}
	if _, err := temporary.Write(wire); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}
	return os.Rename(temporary.Name(), path)
}

func ReadStatusFile(path string) (Status, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return Status{}, err
	}
	if !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > maxStatusFileBytes {
		return Status{}, errors.New("cluster health status must be a bounded regular file")
	}
	file, err := os.Open(path)
	if err != nil {
		return Status{}, err
	}
	defer file.Close()
	wire, err := io.ReadAll(io.LimitReader(file, maxStatusFileBytes+1))
	if err != nil {
		return Status{}, err
	}
	if len(wire) > maxStatusFileBytes {
		return Status{}, errors.New("cluster health status must be a bounded regular file")
	}
	var status Status
	if err := json.Unmarshal(wire, &status); err != nil {
		return Status{}, fmt.Errorf("decode cluster health status: %w", err)
	}
	return status, nil
}

func (status Status) PeerCurrent(serverName string, notBefore time.Time) error {
	switch {
	case status.ObservedAt.Before(notBefore):
		return fmt.Errorf("cluster health was last observed at %s; is the controller running?",
			status.ObservedAt.Format(time.RFC3339))
	case status.MetaLeader == "":
		return errors.New("the metadata group has no leader")
	case slices.Contains(status.Missing, serverName):
		return fmt.Errorf("%s has not joined the metadata group", serverName)
	case slices.Contains(status.Offline, serverName) || !slices.Contains(status.Online, serverName):
		return fmt.Errorf("%s is offline", serverName)
	case slices.ContainsFunc(status.Lagging, func(peer LaggingPeer) bool { return peer.Name == serverName }):
		return fmt.Errorf("%s is still catching up", serverName)
	case !slices.Contains(status.CaughtUp, serverName):
		// Not lagging is not caught up: a lag within the alert threshold,
		// or a follower's view of another follower, proves nothing.
		return fmt.Errorf("%s has not been reported current with zero lag by the metadata leader in this controller's view",
			serverName)
	}
	return nil
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}
